async function httpJson(url, options = {}) {
  const response = await helpers.httpRequest({
    method: options.method || 'GET',
    url,
    headers: options.headers || {},
    body: options.body,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  const status = response.statusCode || response.status || 200;
  return { ok: status >= 200 && status < 300, status, body: response.body ?? response };
}
function cleanJson(text) {
  return String(text || '').replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
}
function parseDecision(text) {
  try {
    const parsed = JSON.parse(cleanJson(text));
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch (_error) {
    return null;
  }
}
const input = $json.body ?? $json;
const headers = $json.headers ?? {};
const token = headers['x-sti-agent-token'] || headers['X-STI-Agent-Token'] || input.agentToken;
if (!$env.N8N_AGENT_TOKEN || token !== $env.N8N_AGENT_TOKEN) {
  throw new Error('Unauthorized WhatsApp agent request');
}
const agentHeaders = { 'content-type': 'application/json', 'x-sti-agent-token': $env.N8N_AGENT_TOKEN };
const resolveUrl = $env.STI_WHATSAPP_RESOLVE_URL || 'http://homepage:3000/api/internal/whatsapp/resolve-user';
const contextUrl = $env.STI_WHATSAPP_CONTEXT_URL || 'http://homepage:3000/api/internal/whatsapp/agent-context';
const actionsUrl = $env.STI_WHATSAPP_ACTIONS_URL || 'http://homepage:3000/api/internal/whatsapp/actions';
const respondUrl = $env.STI_WHATSAPP_RESPOND_URL || 'http://homepage:3000/api/internal/whatsapp/respond';
const ragSearchUrl = $env.STI_RAG_SEARCH_URL || 'http://homepage:3000/api/internal/rag/search';
const message = String(input.message || '').slice(0, 12000);
const chatId = input.chatId;
const resolve = await httpJson(resolveUrl, {
  method: 'POST',
  headers: agentHeaders,
  body: { phone: input.from || input.chatId, from: input.from, chatId: input.chatId, inboundEventId: input.inboundEventId },
});
if (!resolve.ok) throw new Error(resolve.body?.error || 'Unable to resolve WhatsApp user');
if (!resolve.body?.approved) {
  const denial = resolve.body?.reason === 'revoked'
    ? 'This WhatsApp number is no longer approved for the STI Risk staff agent.'
    : 'This WhatsApp number is not approved for the STI Risk staff agent.';
  await httpJson(respondUrl, {
    method: 'POST',
    headers: agentHeaders,
    body: { inboundEventId: input.inboundEventId, chatId, message: denial, metadata: { reason: resolve.body?.reason || 'not_approved' } },
  });
  return [{ json: { ok: true, approved: false, reason: resolve.body?.reason || 'not_approved' } }];
}
if (!message) {
  await httpJson(respondUrl, {
    method: 'POST',
    headers: agentHeaders,
    body: { inboundEventId: input.inboundEventId, chatId, message: 'I can process text WhatsApp messages. Please send the request as text.', metadata: { reason: 'no_text' } },
  });
  return [{ json: { ok: true, approved: true, handled: 'no_text' } }];
}
if (!$env.GEMINI_API_KEY) throw new Error('GEMINI_API_KEY is not configured');
const contextResponse = await httpJson(contextUrl, {
  method: 'POST',
  headers: agentHeaders,
  body: {
    approvalId: resolve.body.approvalId,
    conversationId: input.conversationId,
    inboundEventId: input.inboundEventId,
    message,
  },
});
if (!contextResponse.ok) throw new Error(contextResponse.body?.error || 'Unable to load WhatsApp context');
const context = contextResponse.body || {};
const embeddingModel = $env.GEMINI_EMBEDDING_MODEL || 'gemini-embedding-2';
let vectorResults = [];
try {
  const embedResponse = await httpJson(`https://generativelanguage.googleapis.com/v1beta/models/${embeddingModel}:embedContent`, {
    method: 'POST',
    headers: { 'content-type': 'application/json', 'x-goog-api-key': $env.GEMINI_API_KEY },
    body: { content: { parts: [{ text: message }] }, output_dimensionality: 768 },
  });
  const embedding = embedResponse.body?.embedding?.values || embedResponse.body?.embeddings?.[0]?.values;
  if (embedResponse.ok && embedding) {
    const rag = await httpJson(ragSearchUrl, {
      method: 'POST',
      headers: agentHeaders,
      body: { query: message, embedding, limit: 8 },
    });
    vectorResults = rag.ok ? (rag.body?.results || []) : [];
  }
} catch (_error) {
  vectorResults = [];
}
const ragResults = [...(context.ragResults || []), ...vectorResults].slice(0, 10);
const ragText = ragResults.map((doc, index) => `Document ${index + 1}: ${doc.entityType || doc.entity_type} ${doc.entityId || doc.entity_id}\n${String(doc.content || '').slice(0, 2500)}`).join('\n\n');
const historyText = (context.history || []).map((item) => `${item.direction || item.role || 'message'}: ${item.body || item.summary || item.content || ''}`).join('\n').slice(-6000);
const allowedActions = context.allowedActions || resolve.body.allowedActions || [];
const system = `You are the STI Risk WhatsApp staff agent. You are serving an authenticated staff user over WhatsApp. Use only supplied CRM context and RAG. Keep replies concise for WhatsApp. You may propose at most one action. Allowed actions: ${allowedActions.join(', ') || 'none'}. Never make finance, legal, contract, pricing, destructive, password, or executive approval decisions. Those must become recommendations for review. Return only JSON with keys: reply, action, actionPayload, requiresApproval, reason.`;
const prompt = `Staff user: ${context.user?.name} <${context.user?.email}> (${context.permissionTier})\n\nOperational context:\n${context.context || ''}\n\nRecent WhatsApp/CRM history:\n${historyText || 'No recent history.'}\n\nRAG context:\n${ragText || 'No matching RAG context.'}\n\nUser WhatsApp request:\n${message}`;
const model = $env.GEMINI_WHATSAPP_MODEL || $env.GEMINI_CHAT_MODEL || 'gemini-2.5-flash-lite';
const chatResponse = await httpJson(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`, {
  method: 'POST',
  headers: { 'content-type': 'application/json', 'x-goog-api-key': $env.GEMINI_API_KEY },
  body: {
    system_instruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    generationConfig: { temperature: 0.2, maxOutputTokens: 900, response_mime_type: 'application/json' },
  },
});
if (!chatResponse.ok) throw new Error(chatResponse.body?.error?.message || 'Gemini WhatsApp request failed');
const content = (chatResponse.body?.candidates?.[0]?.content?.parts || []).map((part) => part.text || '').join('').trim();
const decision = parseDecision(content) || { reply: content || 'I could not produce a response.', action: null, actionPayload: null, requiresApproval: true, reason: 'unparseable_model_response' };
let actionResult = null;
const requestedAction = typeof decision.action === 'string' ? decision.action : null;
const requiresApproval = Boolean(decision.requiresApproval) || (requestedAction && !allowedActions.includes(requestedAction));
if (requestedAction && !requiresApproval && ['create_recommendation', 'create_task', 'add_task_comment', 'log_communication'].includes(requestedAction)) {
  const actionResponse = await httpJson(actionsUrl, {
    method: 'POST',
    headers: agentHeaders,
    body: {
      approvalId: resolve.body.approvalId,
      action: requestedAction,
      payload: decision.actionPayload || {},
    },
  });
  actionResult = actionResponse.body;
  if (!actionResponse.ok) {
    await httpJson(actionsUrl, {
      method: 'POST',
      headers: agentHeaders,
      body: {
        approvalId: resolve.body.approvalId,
        action: 'create_recommendation',
        payload: {
          title: 'WhatsApp agent action requires review',
          body: `${decision.reply || 'The WhatsApp agent proposed an action.'}\n\nAction failed: ${actionResponse.body?.error || actionResponse.status}`,
          recommendationType: 'whatsapp_action_review',
          metadata: { requestedAction, inboundEventId: input.inboundEventId },
        },
      },
    });
  }
} else if (requestedAction || requiresApproval) {
  await httpJson(actionsUrl, {
    method: 'POST',
    headers: agentHeaders,
    body: {
      approvalId: resolve.body.approvalId,
      action: 'create_recommendation',
      payload: {
        title: 'WhatsApp request requires review',
        body: decision.reply || 'The WhatsApp request needs staff review.',
        recommendationType: 'whatsapp_action_review',
        metadata: { requestedAction, reason: decision.reason || null, inboundEventId: input.inboundEventId },
      },
    },
  });
}
const reply = String(decision.reply || 'I have logged this for STI Risk staff review.').slice(0, 4000);
const respondMode = requiresApproval && requestedAction ? 'queue' : 'queue';
const respond = await httpJson(respondUrl, {
  method: 'POST',
  headers: agentHeaders,
  body: {
    inboundEventId: input.inboundEventId,
    chatId,
    message: reply,
    mode: respondMode,
    metadata: {
      model,
      requestedAction,
      requiresApproval,
      reason: decision.reason || null,
      usage: chatResponse.body?.usageMetadata || null,
      actionResult,
      ragCount: ragResults.length,
    },
  },
});
if (!respond.ok) throw new Error(respond.body?.error || 'Unable to queue WhatsApp response');
return [{ json: { ok: true, approved: true, model, requestedAction, requiresApproval, response: respond.body, actionResult } }];
